using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;
namespace TriReviewBridge {
 public class MaterialRow {public string Id{get;set;}public string ShortId{get;set;}public string Version{get;set;}public string FileCount{get;set;}public string Status{get;set;}public string Created{get;set;}public object Raw{get;set;}}
 public partial class WorkbenchApp {
  object MaterialsState,MaterialsProof;string MaterialsWorkspace,MaterialsTestSource;bool MaterialsBusy,OpenMaterials;string[] MaterialButtons=new string[]{"MaterialsRefreshButton","MaterialsSourceButton","MaterialsSnapshotButton","MaterialsPackageButton","MaterialsReadButton","MaterialsVerifyButton","MaterialsExportButton","MaterialsDetailsButton"};
  void ClearMaterials(){ClearGovernance();MaterialsState=null;MaterialsWorkspace=null;C<DataGrid>("MaterialsGrid").ItemsSource=null;C<TextBlock>("MaterialsSourceText").Text="选择空间后刷新材料。";C<TextBlock>("MaterialsResultText").Text="没有执行附件上传或原会话投递。";}
  void MaterialsNote(string text){C<TextBlock>("MaterialsResultText").Text=text;}
  void RequireMaterials(){if(MaterialsState==null||CurrentScope==null||MaterialsWorkspace!=CurrentScope.WorkspaceId)throw new InvalidOperationException("请先刷新当前空间的工程材料。");}
  async Task MaterialsAction(Func<Task> action){if(MaterialsBusy)return;MaterialsBusy=true;foreach(string id in MaterialButtons)C<Button>(id).IsEnabled=false;int version=Epoch;try{await action();}catch(Exception e){if(version==Epoch)MaterialsNote("操作未完成："+e.Message);throw;}finally{MaterialsBusy=false;foreach(string id in MaterialButtons)C<Button>(id).IsEnabled=true;}}
  void SetupMaterials(){SetupGovernance();SetupMaterialRecovery();Hook("MaterialsRefreshButton",()=>MaterialsAction(RefreshMaterials));Hook("MaterialsSourceButton",()=>MaterialsAction(RegisterMaterialsSource));Hook("MaterialsSnapshotButton",()=>MaterialsAction(CaptureMaterials));Hook("MaterialsPackageButton",()=>MaterialsAction(BuildMaterials));Hook("MaterialsReadButton",()=>MaterialsAction(ReadMaterials));Hook("MaterialsVerifyButton",()=>MaterialsAction(VerifyMaterials));Hook("MaterialsExportButton",()=>MaterialsAction(ExportMaterials));Hook("MaterialsDetailsButton",()=>{Details("材料版本与完整性哈希",Json.Show(SelectedMaterial().Raw));return Task.FromResult(0);});MainTabs().SelectionChanged+=async(s,e)=>{if(e.Source!=MainTabs()||(MainTabs().SelectedIndex!=2&&MainTabs().SelectedIndex!=3)||MaterialsBusy)return;try{await MaterialsAction(RefreshMaterials);}catch(Exception ex){Fail(ex);}};}
  async Task RefreshMaterials(){string path=ScopePath("materials")+"?projectId="+Uri.EscapeDataString(CurrentScope.ProjectId);int version=Epoch;var data=await Client.Call(path);if(version!=Epoch)return;bool previousBinding=UxBindingControls;UxBindingControls=UxMode;try{RenderGovernance(data);MaterialsState=data;MaterialsWorkspace=CurrentScope.WorkspaceId;var source=Json.Get(data,"source");C<TextBlock>("MaterialsSourceText").Text=source==null?"当前项目未登记来源。仅允许平台内已授权的虚构工程目录；不会读取凪。":"来源："+Json.Str(source,"root")+"\n类型："+Json.Str(source,"type")+" · 已封存快照 "+Json.Arr(Json.Get(data,"snapshots")).Length+" 份。HEAD与实际工作区分别记录。";var grid=C<DataGrid>("MaterialsGrid");var prior=grid.SelectedItem as MaterialRow;var rows=Json.Arr(Json.Get(data,"packages")).Select(p=>new MaterialRow(){Id=Json.Str(p,"id"),ShortId=Json.Str(p,"id").Substring(0,8)+" · "+Json.Arr(Json.Get(data,"tasks")).Where(t=>Json.Str(t,"id")==Json.Str(p,"taskId")).Select(t=>Json.Str(t,"title")).FirstOrDefault(),Version=Json.Str(p,"version"),FileCount=Json.Str(p,"fileCount"),Status=UxMode?UxMaterialStatus(p):"已封存 · 三方未接收",Created=LocalTime(Json.Str(p,"createdAt")),Raw=p}).ToArray();grid.ItemsSource=rows;grid.SelectedItem=prior==null?rows.LastOrDefault():rows.FirstOrDefault(x=>x.Id==prior.Id&&x.Version==prior.Version);}finally{UxBindingControls=previousBinding;}RefreshUxContext();}
  async Task RegisterMaterialsSource(){RequireMaterials();if(Json.Get(MaterialsState,"source")!=null)throw new InvalidOperationException("项目已有唯一主工程来源，不能覆盖原登记。");var d=Dialog("登记虚构工程来源",720,530);var panel=new StackPanel(){Margin=new Thickness(20)};panel.Children.Add(new TextBlock(){Text="本轮只开放平台内虚构工程。输入目录不会执行其中的代码；不访问原生Agent会话。允许的根目录：\n"+String.Join("\n",Json.Arr(Json.Get(MaterialsState,"allowedSourceRoots")).Select(Convert.ToString)),TextWrapping=TextWrapping.Wrap});var path=Field(panel,"实际工程目录",MaterialsTestSource??"",1);var type=new ComboBox(){ItemsSource=new string[]{"directory","git"},SelectedIndex=0,Margin=new Thickness(0,12,0,8)};panel.Children.Add(new TextBlock(){Text="来源类型（Git会核对仓库身份；目录来源明确标记非Git）"});panel.Children.Add(type);var excluded=Field(panel,"额外私有路径，每行一条（默认排除凭证、数据库和运行数据）","",2);Accept(d,panel,"登记唯一主来源");d.Content=new ScrollViewer(){Content=panel};int version=Epoch;if(d.ShowDialog()!=true)return;await Post("materials-source","path",path.Text,"repositoryType",Convert.ToString(type.SelectedItem),"privatePaths",Lines(excluded.Text));if(version!=Epoch)return;await RefreshMaterials();MaterialsNote("主来源已登记；没有发送工程材料。");}
  static string[] Lines(string value){return value.Split('\n').Select(x=>x.Trim()).Where(x=>x.Length>0).ToArray();}
  async Task CaptureMaterials(){RequireMaterials();var source=Json.Get(MaterialsState,"source");if(source==null)throw new InvalidOperationException("请先登记主工程来源。");var d=Dialog("捕获实际 Working Tree",680,460);var p=new StackPanel(){Margin=new Thickness(20)};p.Children.Add(new TextBlock(){Text="捕获实际文件字节，包括允许的未提交和未跟踪文件。凭证和运行文件默认排除；疑似敏感内容会停止打包。不会执行源代码。",TextWrapping=TextWrapping.Wrap});var paths=Field(p,"相对路径，每行一条；留空按安全规则收集（最多500项、8MB）","",7);Accept(d,p,"生成不可变快照");d.Content=p;int version=Epoch;if(d.ShowDialog()!=true)return;var selected=Lines(paths.Text);var result=await Post("materials-snapshot","sourceId",Json.Str(source,"id"),"includeFiles",selected.Length==0?null:selected);if(version!=Epoch)return;await RefreshMaterials();MaterialsNote("已封存工作区快照，文件数："+Json.Str(Json.Get(result,"manifest"),"file_count")+"。请生成对应任务的材料包。");}
  async Task BuildMaterials(){RequireMaterials();var tasks=Json.Arr(Json.Get(MaterialsState,"tasks"));var snapshots=Json.Arr(Json.Get(MaterialsState,"snapshots"));if(tasks.Length==0||snapshots.Length==0)throw new InvalidOperationException("需要当前空间中的文字任务，以及本项目的工程快照。先在任务页创建文字任务。");var d=Dialog("为任务生成版本化材料包",740,650);var p=new StackPanel(){Margin=new Thickness(20)};p.Children.Add(new TextBlock(){Text="仅生成离线文件，不投递给Agent。源文件有变化时需要新快照。",TextWrapping=TextWrapping.Wrap});p.Children.Add(new TextBlock(){Text="所属任务",Margin=new Thickness(0,12,0,4)});var task=new ComboBox(){ItemsSource=tasks.Select(t=>Json.Str(t,"title")).ToArray(),SelectedIndex=0};p.Children.Add(task);p.Children.Add(new TextBlock(){Text="快照（最新在上）",Margin=new Thickness(0,12,0,4)});var snapshot=new ComboBox(){ItemsSource=snapshots.Select(t=>LocalTime(Json.Str(t,"created_at"))+" · "+Json.Str(t,"id").Substring(0,8)).ToArray(),SelectedIndex=0};p.Children.Add(snapshot);var family=Field(p,"已有材料包完整ID（留空生成新系列；填写后新增版本，禁止覆盖）","",1);var objective=Field(p,"审查目标",Json.Str(tasks[0],"title"),3);var acceptance=Field(p,"验收标准，每行一条","核对本版本工程文件及对应证据，保留独立意见。",3);Accept(d,p,"生成不可变版本");d.Content=new ScrollViewer(){Content=p,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};int version=Epoch;if(d.ShowDialog()!=true)return;var result=await Post("materials-package","taskId",Json.Str(tasks[task.SelectedIndex],"id"),"snapshotId",Json.Str(snapshots[snapshot.SelectedIndex],"id"),"packageId",String.IsNullOrWhiteSpace(family.Text)?null:family.Text.Trim(),"objective",objective.Text,"acceptanceCriteria",Lines(acceptance.Text));if(version!=Epoch)return;await RefreshMaterials();var grid=C<DataGrid>("MaterialsGrid");grid.SelectedItem=grid.ItemsSource.Cast<MaterialRow>().First(x=>x.Id==Json.Str(result,"id")&&x.Version==Json.Str(result,"version"));MaterialsNote("材料包 v"+Json.Str(result,"version")+" 已封存并逐字节校验；三方尚未接收。");}
  MaterialRow SelectedMaterial(){RequireMaterials();var row=C<DataGrid>("MaterialsGrid").SelectedItem as MaterialRow;if(row==null)throw new InvalidOperationException("请先选择一个材料版本。");return row;}
  async Task ReadMaterials(){var row=SelectedMaterial();int version=Epoch;var result=await Post("materials-view","packageId",row.Id,"version",Convert.ToInt32(row.Version));if(!UxStillMaterial(row,version))return;if(String.IsNullOrEmpty(SelfTest))Details("材料正文 · 原始文件见导出包",Json.Str(result,"body"));else if(!Json.Str(result,"body").Contains("export const value = 42"))throw new Exception("Native material reader lost source bytes");MaterialsNote("已读取本版完整选定文字视图，未向任何Agent发送。");}
  async Task VerifyMaterials(){var row=SelectedMaterial();int version=Epoch;var result=await Post("materials-verify","packageId",row.Id,"version",Convert.ToInt32(row.Version));if(UxStillMaterial(row,version)){UxRecordMaterialVerification(row,result,version);MaterialsNote(Json.Bool(result,"verified")?"校验通过：本地文件字节、Manifest与原始快照一致。三方尚未接收。":"校验未通过。");}}
  async Task ExportMaterials(){var row=SelectedMaterial();int version=Epoch;var result=await Post("materials-export","packageId",row.Id,"version",Convert.ToInt32(row.Version));if(!UxStillMaterial(row,version))return;MaterialsNote("已导出待交付材料（尚未上传/发送）：\n"+Json.Str(result,"path"));MaterialsProof=Json.D("passed",Json.Str(result,"state")=="PREPARED_NOT_DELIVERED","packageId",row.Id,"version",row.Version,"manifestHash",Json.Str(result,"manifestHash"),"exportPath",Json.Str(result,"path"),"agentReceived",Json.Bool(result,"agentReceived"));}
  async Task RunMaterialsSelfTest(){if(String.IsNullOrEmpty(MaterialsTestSource))throw new Exception("Isolated material fixture required");MainTabs().SelectedIndex=2;while(MaterialsBusy)await Task.Delay(20);await MaterialsAction(RefreshMaterials);await MaterialsAction(RegisterMaterialsSource);await MaterialsAction(CaptureMaterials);await MaterialsAction(BuildMaterials);await MaterialsAction(ReadMaterials);await MaterialsAction(VerifyMaterials);await MaterialsAction(ExportMaterials);await MaterialsAction(PrepareManualHandover);if(MaterialsProof==null||!Json.Bool(MaterialsProof,"passed"))throw new Exception("Native material flow incomplete");}
 }
}